selector_to_html = {"a[href=\"Volute.html#pyskyfire.ducts.volute.Volute.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute.Volute.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exit_diameter</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'fluids'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"VoluteResult.html#pyskyfire.ducts.volute.VoluteResult\" title=\"pyskyfire.ducts.volute.VoluteResult\"><span class=\"pre\">VoluteResult</span></a></span></span></dt><dd><p>Run Aungier\u2019s meanline loss analysis at one operating point.</p></dd>", "a[href=\"VoluteGeometry.html#pyskyfire.ducts.volute.VoluteGeometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute.VoluteGeometry\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VoluteGeometry</span></span></dt><dd><p>Resolved passage geometry around the volute.</p></dd>", "a[href=\"#exceptions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Exceptions<a class=\"headerlink\" href=\"#exceptions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"VoluteResult.html#pyskyfire.ducts.volute.VoluteResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute.VoluteResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VoluteResult</span></span></dt><dd><p>Loss breakdown and station conditions for one volute operating point.</p><p>All loss coefficients are referred to the inlet velocity head, so a total\npressure loss follows as <code class=\"docutils literal notranslate\"><span class=\"pre\">omega</span> <span class=\"pre\">*</span> <span class=\"pre\">rho</span> <span class=\"pre\">*</span> <span class=\"pre\">C5**2</span> <span class=\"pre\">/</span> <span class=\"pre\">2</span></code>.</p></dd>", "a[href=\"VoluteConsistencyWarning.html#pyskyfire.ducts.volute.VoluteConsistencyWarning\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute.VoluteConsistencyWarning\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">exception</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VoluteConsistencyWarning</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/builtins/exceptions.html#RuntimeWarning\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">RuntimeWarning</span></code></a></p><p>Volute inputs are mutually inconsistent or outside a model\u2019s range.</p></dd>", "a[href=\"Volute.html#pyskyfire.ducts.volute.Volute\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute.Volute\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Volute</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">section</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_law</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exit_cone</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tilt</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">181</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A volute or collector resolved from a section family and an area law.</p><p class=\"rubric\">Notes</p><p>Geometry is resolved on construction and is independent of the operating\npoint, so one volute can be solved at several mass flows.</p><p>Tilt rotates the section plane rigidly, and rotation mirrors the whole\npassage about a plane through the axis, so both change where the passage\nsits in space but leave every scalar in the loss analysis unchanged. They\nmatter for packaging and for <a class=\"reference internal\" href=\"#pyskyfire.ducts.volute.Volute.sweep\" title=\"pyskyfire.ducts.volute.Volute.sweep\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">sweep()</span></code></a>, not for pressure loss.</p></dd>", "a[href=\"#references\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">\u00b6</a></h2><p>Aungier, R. H., <em>Centrifugal Compressors: A Strategy for Aerodynamic Design and\nAnalysis</em>, ASME Press, 2000. Sections 5.7 (Eqs. 5-105 to 5-110) and 11.2\n(Eqs. 11-1 to 11-5).</p><p>Weber, C. R. and Koronowski, M. E., \u201cMeanline Performance Prediction of Volutes\nin Centrifugal Compressors,\u201d ASME 86-GT-216, 1986.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.ducts.volute\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.volute<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.volute\" title=\"Link to this heading\">\u00b6</a></h1><p>Volute geometry generation and one-dimensional loss analysis.</p><p>A <a class=\"reference internal\" href=\"Volute.html#pyskyfire.ducts.volute.Volute\" title=\"pyskyfire.ducts.volute.Volute\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Volute</span></code></a> resolves its own geometry on construction: it sweeps the\npolar angle from the tongue, and at each station solves the area law for the\ncross-section size that satisfies it. <a class=\"reference internal\" href=\"Volute.html#pyskyfire.ducts.volute.Volute.solve\" title=\"pyskyfire.ducts.volute.Volute.solve\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Volute.solve()</span></code></a> then runs Aungier\u2019s\nmeanline loss analysis over the resolved geometry.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
